// Availability maths: series vs parallel
const series = (...a) => a.reduce((p, x) => p * x, 1);
const parallel = (...a) => 1 - a.reduce((p, x) => p * (1 - x), 1);

console.log(series(0.999, 0.999, 0.9995));        // ~0.9975: three dependencies in a chain
console.log(parallel(0.99, 0.99));                 // 0.9999: two redundant 99% components
const downtimePerYearMin = (avail) => (1 - avail) * 365 * 24 * 60;
console.log(downtimePerYearMin(0.999), downtimePerYearMin(0.9999));   // ~526 min, ~52.6 min

-- Postgres covering several "other database" needs before you add infrastructure
CREATE TABLE products (
  id          bigserial PRIMARY KEY,
  name        text NOT NULL,
  attrs       jsonb NOT NULL DEFAULT '{}',          -- document-style flexible attributes
  embedding   vector(384),                          -- pgvector for similarity search
  search      tsvector GENERATED ALWAYS AS (to_tsvector('english', name)) STORED
);
CREATE INDEX products_attrs_gin  ON products USING gin (attrs);       -- query inside JSON
CREATE INDEX products_search_gin ON products USING gin (search);      -- full-text search
CREATE INDEX products_emb_hnsw   ON products USING hnsw (embedding vector_cosine_ops);

-- a job queue without a broker
SELECT id FROM jobs WHERE status = 'pending' ORDER BY id LIMIT 10 FOR UPDATE SKIP LOCKED;

// Repository interface keeps the store swappable; the outbox keeps derived stores consistent
// (1) The system of record (Postgres) and the derived search index are updated from ONE transaction + events
await db.tx(async (t) => {
  const product = await t.products.insert(input);
  await t.outbox.insert({ type: "ProductUpserted", payload: { id: product.id } });   // consumed by an indexer
});

// (2) Indexer consumer: idempotent, rebuildable
async function onProductUpserted({ id }) {
  const p = await db.products.find(id);
  if (!p) return search.delete("products", id);           // deleted meanwhile
  await search.index("products", id, { name: p.name, attrs: p.attrs });   // upsert by id = idempotent
}
